package vn.edu.eaut.lab6.controller; import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/login") public class LoginServlet extends HttpServlet{protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.setCharacterEncoding("UTF-8");String u=q.getParameter("username"),pw=q.getParameter("password"),role=null;if("admin".equals(u)&&"123456".equals(pw))role="ADMIN";else if("user".equals(u)&&"123456".equals(pw))role="USER";if(role!=null){HttpSession s=q.getSession();s.setAttribute("username",u);s.setAttribute("role",role);s.setAttribute("loginTime",new java.util.Date());p.sendRedirect(q.getContextPath()+"/dashboard");}else{q.setAttribute("error","Sai tên đăng nhập hoặc mật khẩu");q.getRequestDispatcher("/login.jsp").forward(q,p);}}}
